import json,numpy as np
from plan import *
S=json.load(open('/app/output/repair_raw.json'))
S.sort(key=lambda a:-(a['gain2']-a['loss2']))
for K in [50,75,100,125,150,200]:
 for thresh in [12,20,28,40]:
  groups=[];join=0
  for c in [2,3,4,5,6,7,8,9,0,1]:
   ps=[a for a in S[:K] if a['c']==c]
   while ps:
    g=ps.pop(0)['path']
    while ps:
     end=np.array(g[-1][:2]);ds=[min(np.linalg.norm(end-np.array(s['path'][0][:2])),np.linalg.norm(end-np.array(s['path'][-1][:2]))) for s in ps]
     j=int(np.argmin(ds))
     if ds[j]>thresh:break
     p=ps.pop(j)['path'];p=p if np.linalg.norm(end-np.array(p[0][:2]))<=np.linalg.norm(end-np.array(p[-1][:2])) else p[::-1]
     g+=[(g[-1][0],g[-1][1],.4),(p[0][0],p[0][1],.4)]+p;join+=ds[j]
    groups.append({'c':c,'path':g})
  if len(groups)<=53:
   cc=np.load('/app/output/camera_labels.npy');cc=np.array(Image.fromarray(cc.astype('uint8')).resize((N,N),Image.Resampling.NEAREST));
   for a in groups:paint_path(cc,a['path'],a['c'])
   print('K',K,'threshold',thresh,'groups',len(groups),'join',round(join),'accuracy',round(np.mean(cc==lab),4),flush=True)
   if K==125 and thresh==28:
    with open('/app/output/repair.json','w') as f:json.dump(groups,f)
PY
python /app/output/select_repair.py

